CREATE COLUMN TABLE "TEST_AP"."OTCN" ("AbsEntry" INTEGER CS_INT NOT NULL , "CCDNum" NVARCHAR(40) NOT NULL , "Date" LONGDATE CS_LONGDATE, "CustTerm" NVARCHAR(15), "CntrOrigin" NVARCHAR(3), "DirectImp" NVARCHAR(1) DEFAULT 'N' NOT NULL , "CardCode" NVARCHAR(15), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTCN_CCD" ON "TEST_AP"."OTCN" ( "CCDNum" ASC, "DirectImp" ASC )